export function joinSubagentSessions(
  subagents: LiveSubagent[],
  sessions: Map<string, SessionSummary>,
): LiveSubagent[] {
  if (subagents.length === 0) return subagents;
  const sessionIdByHarnessId = new Map<string, string>();
