        if (line === '') {
          if (current.data || current.type) yield current;
          current = { type: '', data: '' };
        } else if (line.startsWith('event:')) {
          current.type = line.slice(6).trim();
        } else if (line.startsWith('data:')) {
          current.data += (current.data ? '\n' : '') + line.slice(5).trim();
